corrected_code:
@login_required
def get_social_connection_token(request, provider_uid):
    account = get_object_or_404(SocialAccount, uid=provider_uid, user=request.user)
    token = SocialToken.objects.filter(account=account).first()
    return JsonResponse({
        'provider': account.provider,
        'uid': account.uid,
        'access_token': token.token if token else None,
        'extra_data': account.extra_data
    })
